import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    n = int(next(iterator))
    m = int(next(iterator))
    t = int(next(iterator))

    tp = int(next(iterator))
    tu = int(next(iterator))
    td = int(next(iterator))

    heights = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        heights.append(row)

    def get_cost(h1, h2):
        if h1 == h2:
            return tp
        elif h1 < h2:
            return tu
        else:
            return td

    best_diff = float('inf')
    best_coords = (1, 1, n, m)

    for r1 in range(n - 2):
        for r2 in range(r1 + 2, n):
            for c1 in range(m - 2):
                for c2 in range(c1 + 2, m):
                    current_time = 0

                    top_row = r1
                    bottom_row = r2
                    left_col = c1
                    right_col = c2

                    for c in range(left_col, right_col + 1):
                        current_time += get_cost(heights[top_row][c], heights[top_row][c+1] if c < right_col else heights[bottom_row][c])

                    for r in range(top_row, bottom_row + 1):
                        if r == top_row:
                            continue
                        if r == bottom_row:
                            current_time += get_cost(heights[r][right_col], heights[r][right_col-1])
                        else:
                            current_time += get_cost(heights[r][right_col], Heights[r+1][right_col] if r < bottom_row else heights[r][right_col])

                    for c in range(right_col, left_col - 1, -1):
                        if c == right_col and r == bottom_row:
                            continue
                        if c == left_col:
                            current_time += get_cost(heights[bottom_row][c], heights[top_row][c])
                        else:
                            current_time += get_cost(heights[bottom_row][c+1], heights[bottom_row][c])

                    for r in range(bottom_row, top_row - 1, -1):
                        if r == bottom_row:
                            continue
                        if r == top_row:
                            current_time += get_cost(heights[r][left_col], heights[r][left_col+1])
                        else:
                            current_time += get_cost(heights[heights[r][left_col], heights[r-1][left_col]])

                    diff = abs(current_time - t)
                    if diff < best_diff:
                        best_diff = diff
                        best_coords = (r1 + 1, c1 + 1, r2 + 1, c2 + 1)

    print(f"{best_coords[0]} {best_coords[1]} {best_coords[2]} {best_coords[3]}")

solve()
